import {
  createVoiceVerification,
  getVoiceVerification,
  type VoiceVerificationDetailsResponse,
  type SignatoryVoiceForm,
} from '~/client';
import type { SignatoryInfoResult } from '~/types/api';
import { useMobilePermissions } from '~/composables/mobile/useMobilePermissions';

const { requestOne } = useMobilePermissions();

export const useVoiceVerificationStore = defineStore('voiceVerification', () => {
  // state
  const recordState = ref<'inactive' | 'starting' | 'streaming' | 'stopped' | 'submitted'>('inactive');
  const isReadyForSubmission = ref<boolean>(false);
  const signatoryInfos = ref<SignatoryInfoResult[]>([]);

  // actions
  async function createVerification(project_id: string) {
    try {
      await requestOne('microphone');
      const response = await createVoiceVerification({ composable: '$fetch', body: { project_id } });
      return response.id;
    } catch (error: any) {
      showToastError(error);
      return null;
    }
  }

  function resetState() {
    recordState.value = 'inactive';
    signatoryInfos.value = [];
    isReadyForSubmission.value = false;
  }

  function setReadyForSubmission() {
    isReadyForSubmission.value = true;
  }

  function setSignatoryInfos(data: SignatoryInfoResult[]) {
    signatoryInfos.value = data.map((item) => {
      const info = signatoryInfos.value.find((info) => info.id === item.id);
      return {
        ...item,
        signed_date: info?.signed_date ? info.signed_date : formatDateToFormat(new Date(), 'yyyy-MM-dd'),
      };
    });
  }

  function addNewSignatory() {
    signatoryInfos.value.push({
      id: crypto.randomUUID(),
      first_name: '',
      middle_name: null,
      last_name: '',
      state: null,
      city: null,
      county: null,
      address_1: '',
      address_2: null,
      zip_code: null,
      validation_result: null,
      signed_date: formatDateToFormat(new Date(), 'yyyy-MM-dd'),
      other_data: {},
    });
  }

  function removeSignatory(index: number) {
    if (index >= 0 && index < signatoryInfos.value.length) {
      signatoryInfos.value.splice(index, 1);
    }
  }

  return {
    recordState,
    signatoryInfos,
    isReadyForSubmission,
    createVerification,
    resetState,
    setSignatoryInfos,
    setReadyForSubmission,
    addNewSignatory,
    removeSignatory,
  };
});
